put(3751,'- لم تُجمع بعد -','مطابقة not collected للفعل جمع المقتنى، لا مجرد العثور عليه.')
put(3762,'سقطت في الماء والتهمتك المخلوقات. انتبه إلى موطئ قدميك، وابحث عن القصب أو عدس الماء أو غيرها من علامات المياه الضحلة لتتمكن من العبور.','تصحيح المبني للمجهول حتى لا يصبح اللاعب من أكل، وduckweed عدس الماء لا طحالب البط.')
put(3763,'تحت السطح مباشرة، أسفل مدينة نوفوسيبيرسك الميتة، يشق العقيد خليبنيكوف طريقه إلى منزله ليقضي ليلة رأس السنة مع ابنه كيريل. لكن أحوال السكان تنذر بالسوء: فالوحل يواصل التهام الأنفاق، وهجمات المتحولين تتزايد، و«المادة الخضراء» الثمينة التي تحميهم من التسمم الإشعاعي توشك على النفاد. ولضمان نجاة أيٍّ منهم، قد يضطر المسؤولون إلى اتخاذ إجراءات قاسية... تتبع رحلة خليبنيكوف وما عاشه في الأيام الأخيرة للحياة في نوفوسيبيرسك، وهي رحلة يقتفي العقيد ميلر أثرها بعد عام. يقدم هذا الفصل الخطي الجديد أسلوب لعب مترو الكلاسيكي الذي تقوده القصة، مع سلاح جديد كليًا هو قاذف اللهب الفتاك، وبيئات ضيقة خانقة، والتوتر المألوف الذي يقشعر له البدن.','تصحيح عودة الأب لابنه وتسلسل تتبع ميلر للرحلة، وتوحيد خليبنيكوف والمتحولين؛ إزالة ركاكة الوصف دون إسقاط محتواه.')
put(3764,'Metro Exodus - العقيدان','حفظ الاسم التجاري للعبة وتوحيده.')
put(3765,'Metro Exodus - قصة سام','حفظ الاسم التجاري للعبة وتوحيده.')
common01='<tab>وأنا جالس في ملجأ كيريل أستمع إلى قصته، تتضح لي الحياة في مترو نوفوسيبيرسك شيئًا فشيئًا. ويتبين أنها لا تختلف كثيرًا عما اعتدته في موسكو: يعيش عامة الناس حياتهم المعتادة، بينما يحميهم أصحاب القوة والمهارة من أخطار هذا العالم.<br><br><tab>أحيانًا يقاتلون ببسالة فينالون إعجاب الجميع، لكنهم في أغلب الأحيان يكدحون بعيدًا عن الأنظار، محرقين الوحل والديدان التي تنخر الأنظمة التي تُبقي المترو كله حيًا...<br><br>'
put(3766,common01,'Common حياتهم المعتادة لا المشتركة؛ slaving يكدحون لا يستعبدون؛ حفظ منظور الراوي الحالي.')
put(3767,common01+'<tab>كان الفارق الحقيقي الوحيد هو الاقتصاد: في موسكو كانت الحياة تدور حول الطلقات المصنّعة في المصانع، أنجع وسائل إزهاق الأرواح، بينما قام كل شيء هنا على «المادة الخضراء»، الشيء الوحيد الذي يحول دون إصابة سكان هذا المترو بالتسمم الإشعاعي وموتهم سريعًا. ليس الفرق كبيرًا، في رأيي.<br><br><tab>ومع ذلك، يصعب تصديق أن هذه المحطات الخاوية كانت قبل عام واحد فقط تعج بأناس يحتفلون بقدوم عام جديد، سيكون عامهم الأخير. لكن الحيوية التي تملأ كيريل وهو يتحدث عن تلك الأيام لا تدع مجالًا للشك: حتى في هذا الجحيم كان ثمة نصيب ضئيل من السعادة والأمل.<br><br>','تصحيح الكدح والحياة المعتادة، وإصلاح الضمائر والاقتصاد والمفارقة بين تجارة الموت والعقار دون تغيير التأمل السردي.')
prefix02=R[3768]['target'].replace('الجوالون','المستكشفون')
put(3768,prefix02,'توحيد اسم مهنة stalkers بالمستكشفين مع إبقاء الصياغة الجيدة.')
put(3769,prefix02+'<tab>بالطبع، لم يكن كيريل ليدرك كل ما كان يمر به أبوه حينها. لكنني واثق من أن قرارات صعبة كانت تنتظره، إذ كان مسؤولًا عن الإشراف على المصادرات نفسها. بصراحة، لا أحسده...<br><br>','إصلاح ترجمة stalkers والبحث وسبب السقوط، مع حفظ فرع تأمل قرارات الأب والمصادرات دون مزجه بالفرع الآخر.')
common03='<tab>حين لا يبقى للمظلومين ما يخسرونه، سيثورون مهما حاولت ثنيهم. عرف رجال أوسكوم أن القتال بات حتميًا بمجرد نفاد «المادة الخضراء»؛ ولم يكن المجهول سوى موعد اندلاعه.<br><br><tab>مهما حاولوا إخضاع المدنيين، ومهما أعدموا منهم، لم يكن ذلك ليغير شيئًا. وحين اندلعت الحرب، لم يبق لأيٍّ من أطرافها خيار سوى القتال حتى النهاية المريرة. ساحة المعركة تروي ما حدث: لم يطلب أحد الرحمة، ولم يمنحها أحد.<br><br>'
put(3771,common03,'Keep in line إخضاع لا إبقاء في طابور؛ no quarter رحمة/أمان لا سؤال وجواب؛ حفظ قسوة الفرع.')
put(3772,common03+'<tab>ومع ذلك، لم أتوقع رؤية عبوات الكلور. كان ينبغي للجنرال الذي حدّثني عنه كيريل أن يدرك أن حتى هذه التدابير القاسية لن تجدي...<br><br>','تصحيح قلب هوية المتحدث عنه: كيريل يروي عن الجنرال، وليس هو الجنرال؛ حفظ تفرع المشهد.')
put(3774,common03+'<tab>ومع ذلك، لم أتوقع رؤية عبوات الكلور. لقد استبد اليأس بأحدهم، لكن حتى هذه التدابير القاسية لم تجدِ نفعًا. وبما أن الجنرال، كما يقول كيريل، اختار إنهاء حياته، فأشك في أنه كان يؤمن بنجاحها، على الأقل في النهاية.<br><br>','تصحيح إخضاع المدنيين والرحمة ومرجع نجاح التدابير، مع حفظ انتحار الجنرال وما يستنتجه الراوي منه.')
put(3775,'<tab>بلغت هدفي، وأشعر أن ثقل سنوات الشك انزاح أخيرًا عن كاهلي. بعدما رأيت الأنفاق الميتة وسمعت قصة كيريل، أدركت أن علينا فعل شيء كي لا تلقى موسكو المصير نفسه.<br><br><tab>لكن إنقاذ المترو ليس سبب نزولي إلى هذه الهوة المشعة. بصراحة، إنه آخر همومي الآن. لست اليوم العقيد ميلر، قائد تنظيم إسبرطة. أنا مجرد أب عجوز مستعد لفعل أي شيء لإنقاذ أبنائه، كما ينبغي لأي أب أن يفعل... وكما فعل خليبنيكوف قبلي.<br><br>','Order of Sparta تنظيم لا وسام؛ توحيد خليبنيكوف وإصلاح تأمل الأب بصياغة طبيعية دون تغيير دافعه.')
for n in range(3779,3789):
    put(n,R[n]['target'].replace('ميلودي','اللحن'),'Melody لحن موسيقي لا نقل صوتي؛ حفظ رقمه.')
put(3798,'حزم المهمات','تصحيح الجمع في Mission Packs وتوحيد مهمات.')
put(3803,'انغمس تمامًا في عالم مترو. يتحداك وضع الحارس الجديد بإخفاء واجهة المعلومات وعلامة التصويب وتقليل الذخيرة وزيادة صعوبة القتال. ومع شرائه تحصل أيضًا على طلقات عسكرية إضافية، تُستخدم عملة في المترو وذخيرة فتاكة كذلك. وتشمل الحزمة بندقية AKSU، وهي بندقية هجومية روسية صغيرة الحجم لكنها فتاكة، ومثالية للقتال في الأماكن الضيقة.','توحيد وضع الحارس وعلامة التصويب، وإزالة القتال الخانق ولفظ رينجر غير الضروري؛ حفظ محتوى الحزمة الأصلية.')
put(3810,'جارٍ تطبيق التغييرات، <shader_compilation_progress>%.','تصحيح صياغة تقدم العملية وفصل المتغير عن النص.')
P['3811']={'decision':'nontranslatable','reason':'رمز زر ديناميكي فقط.'}
put(3812,'لقيت حتفك إثر سقوطك. توخَّ الحذر عند السير في أماكن مرتفعة.','تصحيح تذكير اللاعب والصياغة الحرفية.')
put(3815,'قنبلة مولوتوف','تسمية عربية واضحة للسلاح بدل كوكتيل المنقولة حرفيًا؛ حفظ اسم مولوتوف الخاص.')
put(3819,'Metro Exodus لعبة تصويب ملحمية من منظور الشخص الأول تقدمها 4A Games، تقودها القصة وتجمع القتال الفتاك والتخفي بالاستكشاف ورعب البقاء، في واحد من أكثر عوالم الألعاب قدرة على إشعارك بأنك تعيش داخله. استكشف البرية الروسية عبر مراحل شاسعة غير خطية، وعش قصة مشوقة تمتد عامًا كاملًا، من الربيع والصيف والخريف إلى قلب الشتاء النووي. تستلهم Metro Exodus روايات دميتري غلوخوفسكي، وتواصل قصة أرتيوم في أعظم مغامرات مترو حتى الآن. انطلق في رحلة مذهلة - اصعد إلى أورورا، القاطرة البخارية التي خضعت لتعديلات واسعة، وانضم إلى مجموعة صغيرة من الناجين في بحثهم عن حياة جديدة في الشرق. تجربة بقاء تمنحك حرية الاستكشاف - تربط قصة آسرة أسلوب لعب مترو الكلاسيكي بمراحل جديدة هائلة غير خطية. عالم جميل وعدائي - اكتشف البرية الروسية بعد نهاية العالم، التي تنبض بالحياة بفضل تعاقب الليل والنهار المذهل والطقس المتغير. قتال فتاك وتخفٍّ - اجمع الموارد واصنع ما تحتاج إليه في الميدان لتخصص ترسانة أسلحتك المصنوعة يدويًا، وخض مواجهات تكتيكية مشوقة ضد البشر والمتحولين. اختياراتك تحدد مصير رفاقك - لن ينجو جميع رفاقك من الرحلة؛ فلقراراتك تبعات في قصة آسرة تتيح لك إعادة اللعب مرارًا بتجارب مختلفة. أجواء واندماج لا يضاهيان - شمعة تتراقص في الظلام؛ شهقة متقطعة بينما يكسو الصقيع قناع الغاز؛ وعواء متحول تحمله رياح الليل - ستأخذك مترو إلى عالمها وتثير رعبك كما لم تفعل أي لعبة أخرى...','إصلاح وصف المتجر كاملًا: الصنع لا الحرف، التخصيص لا إشراك الأعداء، مراحل غير خطية لا لعبة مترو مبهمة، تذكير المتحول وتوحيد الاسم التجاري، مع حفظ جميع مزايا الأصل ونبرته.')
put(3820,'Metro Exodus','حفظ الاسم التجاري المعتمد بدل ترجمته حرفيًا.')
put(3821,'اهرب من أنقاض مترو موسكو المحطمة، وانطلق في رحلة ملحمية تمتد عبر القارة في البرية الروسية بعد نهاية العالم. استكشف مراحل شاسعة غير خطية، وانغمس في تجربة بقاء تمنحك حرية الاستكشاف، واتبع قصة مشوقة تمتد عامًا كاملًا في أعظم مغامرات مترو حتى الآن.','تصحيح مستويات بالمراحل وإزالة التكرار عبر القارة عبر، وحفظ حرية تجربة sandbox التي سقطت.')
put(3824,'نفد مرشح قناعك فاختنقت. احرص على صنع مرشحات إضافية أو البحث عنها، واستبدل المرشح عند نفاده.','توحيد craft بالصنع لا إنشاء المرشحات؛ توضيح الضمير عند الاستبدال.')
put(3829,'جاتلينغ','توحيد اسم السلاح مع ترقياته.')
put(3830,'يكشف هذا الجهاز جميع أنواع الإشعاع الخطير. راقب مقياسه عند سماع إشارة التحذير. وإذا تجاوزت القراءة حد المقياس، فغادر المنطقة الملوثة فورًا، وإلا عرّضت نفسك للموت.','القراءة تتجاوز حد المقياس والمنطقة ملوثة إشعاعيًا، لا مصابة؛ صياغة التحذير بوضوح.')
put(3832,'إن كنت تملك منظار رؤية ليلية، فاضغط على <nightvision> لارتدائه أو نزعه.','توحيد اسم المعدة والتعليمات المكررة.')
put(3833,'إذا تشقق زجاج قناع الغاز وعثرت على قناع سليم، فيمكنك استبداله بالتصويب على القناع السليم والضغط باستمرار على <use>','Visor زجاج القناع لا القناع كله؛ توحيد النص المكرر.')
put(3834,'إذا تشقق زجاج قناع الغاز بالكامل، فابحث عن قناع جديد، وإلا فقد تختنق.','Visor زجاج لا حاجب، وإزالة الثقل في الصياغة.')
put(3835,'إذا بدت اللعبة صعبة جدًا، فجرّب ضبط مستوى الصعوبة على «سهل» من قائمة «الإعدادات».','توحيد اسم قائمة الإعدادات والنص المكرر.')
put(3837,'لإبقاء منظار الرؤية الليلية جاهزًا للاستخدام دائمًا، لا تنس استخدام الشاحن.','توحيد اسم الجهاز وصياغة تلميح موجز.')
put(3839,'لا تنس ضخ الهواء في سلاحك الهوائي.','المضخوخ الهواء داخل السلاح، لا السلاح ذاته.')
put(3840,'حاول تجنب بؤر الإشعاع الشديد.','Hotspots بؤر شديدة الإشعاع لا نقاط ساخنة حراريًا.')
put(3843,'لا تنس شحن المصباح ومنظار الرؤية الليلية.','توحيد اسم المعدة.')
put(3844,'يمكنك تجنب قتال قطيع الحراس بأكمله إذا تخلصت من حراسه بصمت.','Watchmen نوع وحوش يتحرك في قطيع لا مجموعة حراس بشر؛ حفظ تمييز رصدها للحراسة.')
put(3845,'يمكنك حمل سلاحين ناريين من أي نوع، بالإضافة إلى سلاح خاص.','Guns تشمل المسدسات أيضًا، وليست بندقيتين فقط.')
put(3847,'احذر عند إطلاق النار على فوانيس الكيروسين؛ فالوقود الذي يتسرب منها سيشتعل، وقد يلفت ذلك انتباه الأعداء إليك. لكن يمكنك الاستفادة منه أيضًا.','تصحيح shoot lanterns من إطلاق الفوانيس إلى إطلاق النار عليها.')
put(3848,'يتيح لك منظار الرؤية الليلية الرؤية في الظلام دون أن يكشف وجودك للعدو كما يفعل المصباح، لكنه يظل بحاجة إلى الشحن.','توحيد اسم الجهاز وحفظ ميزته وحاجته إلى الشحن.')
